// === Tab: mySketch ===
let myShader;
let img;
let uvone;
let uvtwo;

function preload() {
  myShader = createShader(vert, frag);
	img = loadImage("https://openprocessing.org/sketch/1371580/files/uvtestimage.png")
	imgc = loadImage("https://openprocessing.org/sketch/1371580/files/uvcleantwo.bmp")
	uvone = loadImage("https://openprocessing.org/sketch/1371580/files/uv1.png")
	uvtwo = loadImage("https://openprocessing.org/sketch/1371580/files/uv2.png")
}

function setup() {
	let size = 540//max(windowWidth, windowHeight);
	createCanvas(size, size, WEBGL);
	noStroke();
}

function draw() {
	shader(myShader);
	myShader.setUniform('u_res', [width, height]);
	myShader.setUniform('u_time', (millis()/1000/15)%1.0);
	myShader.setUniform('u_uvone', uvone);
	myShader.setUniform('u_uvtwo', uvtwo);
	myShader.setUniform('conf', [0,-1,1,-1,0,1]);
	myShader.setUniform('u_palette', imgc);

	rect(0,0,width,height);
}

// === Tab: vert ===
const vert = `
		attribute vec3 aPosition;
		attribute vec2 aTexCoord;

		varying vec2 vTexCoord;

		void main() {
			vTexCoord = aTexCoord;
			vec4 positionVec4 = vec4(aPosition, 1.0);
			positionVec4.xy = positionVec4.xy * 2.0 - 1.0;
			gl_Position = positionVec4;
		}
`;

// === Tab: frag ===
const frag = `
#ifdef GL_ES
precision mediump float;
#endif

uniform vec2 u_res;
uniform float u_time;
uniform sampler2D u_uvone;
uniform sampler2D u_uvtwo;
uniform float conf[6];
uniform sampler2D u_palette;

void main() {
	float mixrate = clamp(-cos(u_time*6.28318530718)*1.05,-1.0,1.0)*0.5+0.5;
	// vec2 a = vec2(gl_FragCoord.x/u_res.x,1.0-gl_FragCoord.y/u_res.y);
	// vec2 b = vec2(
	// conf[0]*(gl_FragCoord.x/u_res.x) + conf[1]*(gl_FragCoord.y/u_res.y) + conf[2],
	// conf[3]*(gl_FragCoord.x/u_res.x) + conf[4]*(gl_FragCoord.y/u_res.y) + conf[5]
	// );
	vec4 ha = texture2D(u_uvone, vec2(gl_FragCoord.x/u_res.x, 1.0-gl_FragCoord.y/u_res.y));
	vec2 a = ha.xy/ha.b;
	vec4 hb = texture2D(u_uvtwo, vec2(gl_FragCoord.x/u_res.x, 1.0-gl_FragCoord.y/u_res.y));
	vec2 b = hb.xy/hb.b;
	gl_FragColor = texture2D(u_palette, mix(a,b,mixrate))*mix(ha.b,hb.b,mixrate);
}
`;

